argv:
import json,sys,unittest
root,modules,pattern=sys.argv[1],json.loads(sys.argv[2]),sys.argv[3]
sys.path.insert(0,root)
sys.path.insert(0,root+"/scripts")
loader=unittest.TestLoader()
suite=loader.discover(root+"/tests",pattern=pattern) if pattern else loader.loadTestsFromNames(modules)
def flatten(suite):
 for item in suite:
  if isinstance(item,unittest.TestSuite): yield from flatten(item)
  else: yield item.id()
ids=list(flatten(suite))
print(json.dumps({"count":suite.countTestCases(),"ids":ids,"loader_errors":loader.errors}))

